                ['img' => '07-spring-tradition', 'alt_en' => 'A paste of egg, earth and flowers pressed beside a doorway at Lalish for the spring festival', 'alt_ku' => 'هەویرێک لە هێلکە و خاک و گوڵ لە تەنیشت دەرگایەک لە لالش بۆ جەژنی بەهار پەستێنراوە', 'alt_ar' => 'عجينة من البيض والتراب والزهور ملصقة بجانب باب في لالش لعيد الربيع', 'caption_en' => 'Red Wednesday, the Yazidi New Year in April: a paste of egg, earth and flowers is pressed beside the doors.', 'caption_ku' => 'چارشەمبووی سوور، سەری ساڵی ئێزدی لە نیسان: هەویرێک لە هێلکە و خاک و گوڵ لە تەنیشت دەرگاکان دەپەستێنرێت.', 'caption_ar' => 'الأربعاء الأحمر، رأس السنة الإيزيدية في نيسان: تُلصق عجينة من البيض والتراب والزهور بجانب الأبواب.'],
                ['img' => '08-babe-chawish', 'alt_en' => 'Babê Çawîş, the guardian of the Lalish sanctuary, in white robes', 'alt_ku' => 'بابێ چاوش، پارێزەری پیرۆزگای لالش، بە جلی سپی', 'alt_ar' => 'بابي جاويش، حارس حرم لالش، في ثياب بيضاء', 'caption_en' => 'Babê Çawîş, who keeps the sanctuary and receives its pilgrims.', 'caption_ku' => 'بابێ چاوش، کە پیرۆزگاکە دەپارێزێت و زیارەتکەرانی پێشوازی دەکات.', 'caption_ar' => 'بابي جاويش، الذي يرعى الحرم ويستقبل حجاجه.'],
