        ['type' => 'facts', 'data' => [
            'layout' => 'list',
            'heading_en' => 'The customs of the valley', 'heading_ku' => 'نەریتەکانی دۆڵەکە', 'heading_ar' => 'عادات الوادي',
            'items' => [
                ['label_en' => 'Barefoot', 'label_ku' => 'بە پێی پەتی', 'label_ar' => 'حفاة', 'text_en' => 'The earth of Lalish is sacred: it may not be walked on in shoes or spat on, and no one enters the temple bareheaded.', 'text_ku' => 'خاکی لالش پیرۆزە: نابێت بە پێڵاوەوە بەسەریدا بڕۆیت یان تفی لێ بکەیت، و کەس بە سەری ڕووت ناچێتە ناو پەرستگاکە.', 'text_ar' => 'تراب لالش مقدس: لا يجوز المشي عليه بالأحذية ولا البصق عليه، ولا يدخل أحد المعبد حاسر الرأس.'],
                ['label_en' => 'The threshold', 'label_ku' => 'بەردەرگاکە', 'label_ar' => 'العتبة', 'text_en' => 'At the temple door pilgrims step over the threshold, never on it, and kiss the stone of the doorway and the wall beside it.', 'text_ku' => 'لە دەرگای پەرستگا زیارەتکەران بەسەر بەردەرگاکەدا هەنگاو دەنێن، هەرگیز لەسەری نا، و بەردی دەرگاکە و دیواری تەنیشتی ماچ دەکەن.', 'text_ar' => 'عند باب المعبد يخطو الحجاج فوق العتبة، لا عليها أبداً، ويقبّلون حجر المدخل والجدار بجانبه.'],
                ['label_en' => 'Three times across', 'label_ku' => 'سێ جار بەسەریدا', 'label_ar' => 'ثلاث مرات عبره', 'text_en' => 'The Sarat Bridge — ten metres long, three wide — is crossed three times at a run after washing; a soul heavy with sin, it is said, would fall.', 'text_ku' => 'پردی سیرات — دە مەتر درێژ، سێ مەتر پان — دوای خۆشتن سێ جار بە ڕاکردن دەبڕدرێت؛ دەوترێت گیانێکی قورس بە گوناه دەکەوێت.', 'text_ar' => 'جسر الصراط — طوله عشرة أمتار وعرضه ثلاثة — يُعبر ثلاث مرات ركضاً بعد الاغتسال؛ ويُقال إن الروح المثقلة بالخطيئة تسقط.'],
                ['label_en' => 'The White Spring', 'label_ku' => 'کانییا سپی', 'label_ar' => 'العين البيضاء', 'text_en' => 'Kaniya Sipî, said to be the only water that stayed clear through the Flood, is where Yazidis are sealed with water as infants or pilgrims. Non-Yazidis do not enter it, and a married couple may not enter together.', 'text_ku' => 'کانییا سپی، کە دەوترێت تاکە ئاوە کە بە درێژایی لافاوەکە ڕوون مایەوە، ئەو شوێنەیە ئێزدییەکان وەک ساوا یان زیارەتکەر بە ئاو مۆر دەکرێن. نائێزدییەکان ناچنە ناوی، و جووتێکی هاوسەرگیریکردوو نابێت پێکەوە بچنە ناوی.', 'text_ar' => 'كانيا سبي، التي يُقال إنها الماء الوحيد الذي بقي صافياً طوال الطوفان، هي حيث يُختم الإيزيديون بالماء أطفالاً أو حجاجاً. لا يدخلها غير الإيزيديين، ولا يجوز لزوجين دخولها معاً.'],
                ['label_en' => 'Knots in cloth', 'label_ku' => 'گرێ لە پارچەدا', 'label_ar' => 'عقد في القماش', 'text_en' => 'Inside the hall coloured cloths hang from the pillars; a pilgrim unties another\'s knot, releasing that wish, and ties their own.', 'text_ku' => 'لە ناو هۆڵەکەدا پارچەی ڕەنگاوڕەنگ لە ستوونەکانەوە هەڵواسراون؛ زیارەتکەرێک گرێی کەسێکی تر دەکاتەوە، ئەو ئاواتە ئازاد دەکات، و هی خۆی دەبەستێت.', 'text_ar' => 'في القاعة تتدلى أقمشة ملوّنة من الأعمدة؛ يحلّ الحاج عقدة غيره، فيطلق تلك الأمنية، ويعقد عقدته.'],
                ['label_en' => 'Lamps at dusk', 'label_ku' => 'چرا لە ئێوارەدا', 'label_ar' => 'القناديل عند الغسق', 'text_en' => 'Every evening wicks are lit in olive oil in the niches of the sanctuary and the shrines across the valley — the oldest rite of the place, older than any building in it.', 'text_ku' => 'هەموو ئێوارەیەک پڵیتە لە زەیتی زەیتووندا لە تاقەکانی پیرۆزگاکە و پیرۆزگاکانی سەرانسەری دۆڵەکەدا هەڵدەکرێن — کۆنترین ڕێوڕەسمی شوێنەکە، لە هەر بینایەکی ناوی کۆنتر.', 'text_ar' => 'كل مساء تُشعل فتائل في زيت الزيتون في كوى الحرم والمزارات عبر الوادي — أقدم شعيرة في المكان، أقدم من أي بناء فيه.'],
                ['label_en' => 'The year', 'label_ku' => 'ساڵەکە', 'label_ar' => 'السنة', 'text_en' => 'Çarşema Sor, Red Wednesday, the New Year, falls on the first Wednesday on or after 14 April; the Feast of the Assembly, when the whole community gathers, runs from 6 to 13 October.', 'text_ku' => 'چارشەمبووی سوور، سەری ساڵ، لە یەکەم چوارشەممە لە ١٤ی نیسان یان دوای ئەودا دەکەوێت؛ جەژنی جەماعییە، کاتێک هەموو کۆمەڵگەکە کۆدەبێتەوە، لە ٦ تا ١٣ی تشرینی یەکەمە.', 'text_ar' => 'يقع الأربعاء الأحمر، رأس السنة، في أول أربعاء يوافق ١٤ نيسان أو يليه؛ ويمتد عيد الجماعية، حين تجتمع الجماعة كلها، من ٦ إلى ١٣ تشرين الأول.'],
            ],
        ]],

